<?php
require __DIR__.'/includes/bootstrap.php';require_auth();require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';
if($_SERVER['REQUEST_METHOD']==='POST')require_permission('inventory.adjust');
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$product=(int)($_POST['product_id']??0);$branch=(int)($_POST['branch_id']??0);$brand=(int)($_POST['brand_id']??0);$qty=(float)($_POST['quantity']??0);$direction=($_POST['direction']??'increase')==='decrease'?'decrease':'increase';
    try{if(!$product||!$branch||!$brand||$qty<=0)throw new RuntimeException('Complete the product, branch, brand and quantity.');enforce_branch_scope($branch);$pdo->beginTransaction();$ref=next_reference($pdo,'ADJ','stock_adjustments');$s=$pdo->prepare('INSERT INTO stock_adjustments(reference_no,adjustment_date,branch_id,brand_id,product_id,direction,quantity,reason,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$ref,$_POST['date']??date('Y-m-d'),$branch,$brand,$product,$direction,$qty,trim($_POST['reason']??'Physical stock count'),trim($_POST['notes']??''),user()['id']]);$id=(int)$pdo->lastInsertId();ledger($pdo,['product_id'=>$product,'branch_id'=>$branch,'brand_id'=>$brand,'transaction_type'=>$direction==='increase'?'adjustment_in':'adjustment_out','reference_type'=>'adjustment','reference_id'=>$id,'reference_no'=>$ref,'quantity_in'=>$direction==='increase'?$qty:0,'quantity_out'=>$direction==='decrease'?$qty:0]);audit($pdo,'create','stock_adjustments',$id,null,['direction'=>$direction,'quantity'=>$qty]);$pdo->commit();flash('success','Available stock updated successfully.');redirect('inventory.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());redirect('inventory.php?action=adjust');}
}
$adjust=($_GET['action']??'')==='adjust';render_header('Inventory','inventory');page_title('Available Stock','LIVE QUANTITY COUNT','See every product’s current available quantity, usage and wastage.',$adjust?'':'Update Stock Count',app_url('inventory.php?action=adjust'));
if($adjust):$branches=options($pdo,'branches');$brands=options($pdo,'brands');$products=$pdo->query('SELECT p.id,CONCAT(p.name," · ",u.symbol) label FROM products p JOIN units u ON u.id=p.unit_id WHERE p.status="active" AND p.deleted_at IS NULL ORDER BY p.name')->fetchAll();?>
<article class="card form-card"><div class="card-head"><div><h2>Update available quantity</h2><small>Use Increase to add counted stock or Decrease to correct a physical count.</small></div><span class="status pending">COUNT ADJUSTMENT</span></div><form method="post"><?=csrf_field()?><div class="form-grid"><label>Date<input type="date" name="date" value="<?=date('Y-m-d')?>" required></label><label>Change<select name="direction"><option value="increase">Add quantity</option><option value="decrease">Remove quantity</option></select></label><label>Branch<select name="branch_id" required><option value="">Choose branch</option><?php foreach($branches as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Brand<select name="brand_id" required><option value="">Choose brand</option><?php foreach($brands as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Product<select name="product_id" required><option value="">Choose product</option><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Quantity<input type="number" inputmode="decimal" step="0.001" min="0.001" name="quantity" required></label><label class="full">Reason<input name="reason" required value="Physical stock count"></label><label class="full">Note (optional)<textarea name="notes"></textarea></label></div><div class="form-actions"><a class="btn" href="<?=app_url('inventory.php')?>">Cancel</a><button class="btn primary">Update available stock</button></div></form></article>
<?php else:[$period,$from,$to,$branch,$brand]=page_params();$join='it.product_id=p.id';$args=[];if($branch){$join.=' AND it.branch_id=?';$args[]=$branch;}if($brand){$join.=' AND it.brand_id=?';$args[]=$brand;}$sql='SELECT p.id,p.name,p.sku,u.symbol,p.minimum_stock,COALESCE(SUM(it.quantity_in-it.quantity_out),0) available,COALESCE(SUM(CASE WHEN it.transaction_type IN("receiving","opening","adjustment_in","transfer_in","return") THEN it.quantity_in ELSE 0 END),0) added,COALESCE(SUM(CASE WHEN it.transaction_type="usage" THEN it.quantity_out ELSE 0 END),0) used,COALESCE(SUM(CASE WHEN it.transaction_type="wastage" THEN it.quantity_out ELSE 0 END),0) wastage FROM products p JOIN units u ON u.id=p.unit_id LEFT JOIN inventory_transactions it ON '.$join.' WHERE p.deleted_at IS NULL AND p.status="active" GROUP BY p.id,p.name,p.sku,u.symbol,p.minimum_stock ORDER BY p.name';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$totalItems=count($rows);$low=count(array_filter($rows,fn($r)=>(float)$r['available']<=(float)$r['minimum_stock']));?>
<div class="inventory-kpis"><div><span>Active products</span><b><?=$totalItems?></b></div><div><span>Low / empty</span><b><?=$low?></b></div><div><span>View</span><b><?=$branch||$brand?'Filtered':'All locations'?></b></div></div><div class="page-head" style="margin-top:-8px"><div></div><?php filter_bar($pdo,false);?></div><article class="card table-card"><div class="table-toolbar"><div><b><?=$totalItems?> products</b><small style="display:block;color:var(--muted);margin-top:4px">All balances are calculated automatically</small></div><input placeholder="Search products…" data-table-search></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Added</th><th>Used</th><th>Wastage</th><th>Available</th><th>Status</th><th>Quick action</th></tr></thead><tbody><?php foreach($rows as $r):$isLow=(float)$r['available']<=(float)$r['minimum_stock'];?><tr><td data-label="Product"><b><?=e($r['name'])?></b><small style="display:block;color:var(--muted)"><?=e($r['sku'])?> · <?=e($r['symbol'])?></small></td><td data-label="Added"><?=number_format($r['added'],3).' '.e($r['symbol'])?></td><td data-label="Used"><?=number_format($r['used'],3).' '.e($r['symbol'])?></td><td data-label="Wastage"><?=number_format($r['wastage'],3).' '.e($r['symbol'])?></td><td data-label="Available"><b><?=number_format($r['available'],3).' '.e($r['symbol'])?></b></td><td data-label="Status"><span class="status <?=$isLow?'cancelled':''?>"><?=$isLow?'Low / empty':'Available'?></span></td><td data-label="Quick action"><a class="btn small" href="<?=app_url('wastage.php')?>">Add wastage</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7"><div class="empty"><div class="empty-icon"><i data-icon="boxes"></i></div>No products yet.</div></td></tr><?php endif;?></tbody></table></div></article><?php endif;render_footer('inventory');
